contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to deposit then attempts withdraw; msg.sender for c calls is this contract
    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit);

        // Record balance before any operations
        uint beforeRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // Attempt to add deposit to c (may be zero)
        c.addToBalance{value: deposit}(); if (__ESBMC_reverted()) return;

        // Record after deposit (view calls only)
        uint afterRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // Now try withdraw and capture whether it reverted
        bool withdrewReverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrewReverted = true;
        } else {
            withdrewReverted = false;
        }

        uint finalRecorded = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint finalContractBal = address(c).balance;

        // General rule:
        // If withdrawBalance succeeded (did not revert) then the recorded balance for this test contract is zero
        // and the contract's Ether balance did not increase (it should be <= previous contract balance).
        // If withdrawBalance reverted then recorded balance is unchanged from afterRecorded.
        assert((!withdrewReverted && finalRecorded == 0 && finalContractBal <= afterContractBal) || (withdrewReverted && finalRecorded == afterRecorded));
    }

    // allow receiving Ether for test setup
    receive() external payable {}
}

